import { test, expect, type Page } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/reg1-r12.json'), colorScheme: 'dark' });

const ownButton = (page: Page) => page.getByRole('button', { name: /הסטורי שלי/ });

// Открыть /discover при заданном окне и дождаться, что кнопка «הסטורי שלי» — верхний элемент в своём центре (ушёл сплэш).
async function openDiscoverAt(page: Page, width: number, height: number) {
  await page.setViewportSize({ width, height });
  await page.goto('/discover');
  const btn = ownButton(page);
  await expect(btn).toBeVisible();
  await expect
    .poll(() =>
      btn.evaluate((el) => {
        const r = el.getBoundingClientRect();
        const top = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2);
        return !!top && el.contains(top);
      }),
    )
    .toBe(true);
}

// Кружки ряда сторис: кнопки с аватаром в зоне ряда (y 40…130); кружок — первый вложенный div кнопки.
async function rowCircles(page: Page) {
  return page.evaluate(() =>
    [...document.querySelectorAll('button, [role=button]')]
      .filter((b) => {
        const r = b.getBoundingClientRect();
        return r.top > 40 && r.top < 130 && r.width > 0 && !!b.querySelector('img[src*="/avatars/"]');
      })
      .map((b) => {
        const c = b.querySelector('div')!.getBoundingClientRect();
        return { own: (b.textContent ?? '').includes('הסטורי שלי'), w: c.width, h: c.height };
      }),
  );
}

test.describe('Раунд 13: кружки сторис 62/60/57/52 (#c94032)', () => {
  test('Кружок «הסטורי שלי» 62×62 при 390 и 430 @iphone @prod-safe', async ({ page }) => {
    for (const [width, height] of [[390, 844], [430, 932]]) {
      // 1. Viewport 390×844, `/discover`, дождаться «הסטורי שלי» (затем то же на 430×932).
      await openDiscoverAt(page, width, height);

      // 2. Снять rect кружка «הסטורי שלי» и всех остальных кружков ряда.
      const own = ownButton(page).locator('div').first();
      await expect
        .poll(async () => {
          const b = (await own.boundingBox())!;
          return [b.width, b.height];
        }, { message: `кружок «הסטורי שלי» при ширине ${width}` })
        .toEqual([62, 62]);
      const box = (await own.boundingBox())!;
      expect(Math.abs(box.width - 62), `ширина при ${width}`).toBeLessThanOrEqual(0.5);
      expect(Math.abs(box.height - 62), `высота при ${width}`).toBeLessThanOrEqual(0.5);

      // Чужие кружки (если есть) того же размера, что свой.
      const circles = await rowCircles(page);
      for (const c of circles.filter((c) => !c.own)) {
        expect(Math.abs(c.w - box.width), `чужой кружок: ширина при ${width}`).toBeLessThanOrEqual(0.5);
        expect(Math.abs(c.h - box.height), `чужой кружок: высота при ${width}`).toBeLessThanOrEqual(0.5);
      }
    }
  });
});
